css:
/* add this to your :root variables */
.checkbox {
  --light: rgba(207, 205, 205, 0.425);
  --primary-color: #8c00ff;
  --duration: 0.3s;
  --ease: ease-in-out;
}

/* hide checkbox */
.checkbox input[type="checkbox"] {
  display: none;
}

.checkbox label {
  align-items: center;
  cursor: pointer;
  display: flex;
}

.checkbox label span {
  margin-left: 8px;
}

.checkbox svg {
  height: 30px;
  width: 30px;
}

/* svg rectangle property */
.checkbox svg > rect {
  fill: var(--light);
  stroke: #8c00ff;
  /* responsive values */
  stroke-dasharray: 400%;
  stroke-dashoffset: 400%;
  transition: var(--duration) stroke-dashoffset var(--ease);
}

/* svg check property */
.checkbox svg path {
  stroke: var(--primary-color);
  /* responsive values */
  stroke-dasharray: 100%;
  stroke-dashoffset: 100%;
  transition: var(--duration) stroke-dashoffset var(--ease);
}

.checkbox input[type="checkbox"]:checked + label svg > rect,
  .checkbox input[type="checkbox"]:checked + label svg path {
  stroke-dashoffset: 0;
}
